public class Solution {
    static final class UserProfile {
        private final String username;
        private final Date createdDate;

        UserProfile(String username, Date createdDate) {
            this.username = username;
            this.createdDate = new Date(createdDate.getTime()); // Defensive copy on construction
        }

        public String getUsername() {
            return username;
        }

        public Date getCreatedDate() {
            return new Date(createdDate.getTime()); // Defensive copy on retrieval
        }
    }

    public static void main(String[] args) {
        Date originalDate = new Date(1700000000000L);
        UserProfile user = new UserProfile("Akshat", originalDate);

        // Attempt external mutation via getter
