        leakedDate.setTime(0L);

        System.out.println("User name: " + user.getUsername());
        System.out.println("Internal date preserved: " + (user.getCreatedDate().getTime() == 1700000000000L));
    }
}

public class Solution {
    static class EagerSingleton {
        private static final EagerSingleton INSTANCE = new EagerSingleton();
        private EagerSingleton() {}
        public static EagerSingleton getInstance() { return INSTANCE; }
    }

    static class LazySingleton {
        private static volatile LazySingleton instance;
        private LazySingleton() {}
        public static LazySingleton getInstance() {
            if (instance == null) {
                synchronized (LazySingleton.class) {
                    if (instance == null) {
                        instance = new LazySingleton();
                    }
                }
            }
            return instance;
        }
    }

    public static void main(String[] args) {
        EagerSingleton e1 = EagerSingleton.getInstance();
        EagerSingleton e2 = EagerSingleton.getInstance();
        LazySingleton l1 = LazySingleton.getInstance();
        LazySingleton l2 = LazySingleton.getInstance();

        System.out.println("Eager instances identical: " + (e1 == e2));
        System.out.println("Lazy instances identical: " + (l1 == l2));
    }
}

