public class Solution {
    interface Contract {
        int CAPACITY = 100; // Implicitly public static final
        void execute();     // Implicitly public abstract
    }

    public static void main(String[] args) throws Exception {
        Field field = Contract.class.getField("CAPACITY");
        int fieldMods = field.getModifiers();
        System.out.println("Field is public: " + Modifier.isPublic(fieldMods));
        System.out.println("Field is static: " + Modifier.isStatic(fieldMods));
        System.out.println("Field is final: " + Modifier.isFinal(fieldMods));

        Method method = Contract.class.getMethod("execute");
        int methodMods = method.getModifiers();
        System.out.println("Method is public: " + Modifier.isPublic(methodMods));
        System.out.println("Method is abstract: " + Modifier.isAbstract(methodMods));
    }
}

