import java.lang.reflect.Field;

public class Solution {
    static class SecureEnclave {
        private String secureToken = "ENCLAVE_TOKEN_ALPHA";

        public String getSecureToken() {
            validateCaller();
            return secureToken;
        }

        private void validateCaller() {
            StackWalker walker = StackWalker.getInstance(StackWalker.Option.RETAIN_CLASS_REFERENCE);
            Class<?> caller = walker.walk(frames -> frames.skip(2).findFirst().map(StackWalker.StackFrame::getDeclaringClass).orElse(null));
            if (caller != Solution.class) {
                throw new SecurityException("Unauthorized caller!");
            }
        }
    }

    public static void main(String[] args) throws Exception {
        SecureEnclave enclave = new SecureEnclave();
        System.out.println("Standard authorized read: " + enclave.getSecureToken());

        Field field = SecureEnclave.class.getDeclaredField("secureToken");
        field.setAccessible(true);
        field.set(enclave, "COMPROMISED_TOKEN");
        System.out.println("Reflective bypass modified field: " + field.get(enclave));
    }
}

