import java.lang.reflect.Constructor;
import java.lang.reflect.Modifier;

public class Solution {
    // Package-private internal class with an accidental public constructor leak
    static class InternalHelper {
        public InternalHelper() {} 
        void runInternal() {}
    }

    public static void auditClassEncapsulation(Class<?> clazz) {
        boolean isClassPackagePrivate = !Modifier.isPublic(clazz.getModifiers());
        System.out.println("Auditing class: " + clazz.getSimpleName());
        System.out.println("Is package-private class: " + isClassPackagePrivate);

        for (Constructor<?> c : clazz.getDeclaredConstructors()) {
            if (isClassPackagePrivate && Modifier.isPublic(c.getModifiers())) {
                System.out.println("Warning: Package-private class exposes public constructor!");
            }
        }
    }

    public static void main(String[] args) {
        auditClassEncapsulation(InternalHelper.class);
    }
}
